import { createRequire } from 'node:module'

const require = createRequire(import.meta.url)
const postcss = require('./lib/postcss.js')

if (typeof postcss.parse !== 'function') {
  console.log('postcss.parse does not exist on this version')
  process.exitCode = 125
} else {
  const root = postcss.parse(`
.cls {
  color: orange;
}`)
  const nodes = root.nodes[0].nodes
  let error = null
  try {
    JSON.stringify(nodes)
  } catch (e) {
    if (e instanceof TypeError && /inputs\.get is not a function/.test(e.message)) {
      error = e
    } else {
      throw e
    }
  }
  if (error) {
    console.log(
      'WHOBROKEIT_BUG: expected JSON.stringify(root.nodes[0].nodes) to succeed, ' +
        'but it threw TypeError: ' + error.message
    )
    process.exitCode = 1
  } else {
    process.exitCode = 0
  }
}
